import sys
from collections import defaultdict
lines = sys.stdin.read().splitlines()
if lines:
    k = int(lines[0])
    adj = defaultdict(list)
    for line in lines[1:1+k]:
        ft = line.split()
        if len(ft) == 2: adj[ft[0]].append(ft[1])
    for u in adj: adj[u].sort(reverse=True)
    route = []
    def dfs(u):
        while adj[u]: dfs(adj[u].pop())
        route.append(u)
    dfs('JFK')
    print(' '.join(reversed(route)))
